//! chatter: Zenoh publisher for `ros2/std/StringStamped` on `dev01/demo/pubber/zenoh/chatter`.
//!
//! Generated by `sb pub add` (L3). Re-running `sb pub edit/rm` regenerates
//! or removes this file. Hand-edits will be overwritten on the next
//! mutation — keep payload serialization in your own module.
//!
//! # Wire encoding
//!
//! Every sample carries the Zenoh encoding [`WIRE_TAG`] (`application/protobuf;ros2/std/StringStamped`),
//! so subscribers such as `sb topic listen` know how to read the payload.
//! [`ChatterPublisher::publish`] encodes a prost message (requires the
//! `prost` crate); [`ChatterPublisher::publish_bytes`] sends bytes you
//! serialized yourself.
//!
//! # Default wire path
//!
//! `dev01/demo/pubber/zenoh/chatter` — built from the per-segment defaults below.
//! Override any segment at construction via
//! `open_with(&session, TopicOverrides { module: Some("..".into()), ..Default::default() })`
//! for swarm-instance discrimination.
//!
//! # Example usage
//!
//! ```ignore
//! #[path = "swarmbotix_io/publishers/chatter.rs"]
//! mod chatter;
//!
//! use zenoh::Wait;
//!
//! fn main() -> Result<(), Box<dyn std::error::Error>> {
//!     let session = zenoh::open(zenoh::Config::default()).wait()?;
//!     let publisher = chatter::ChatterPublisher::open(&session)?;
//!     let msg = StringStamped::default(); // your prost-generated type
//!     publisher.publish(&msg)?;
//!     Ok(())
//! }
//! ```

use zenoh::Wait;
use zenoh::bytes::Encoding;

/// Zenoh encoding stamped on every sample this publisher sends.
pub const WIRE_TAG: &str = "application/protobuf;ros2/std/StringStamped";

// Per-segment defaults baked at `sb pub add` time. Override at
// construction (`open_with`) to vary the wire path without regenerating.
pub const DEFAULT_DEVICE: &str = "dev01";
pub const DEFAULT_WORKSPACE: &str = "demo";
pub const DEFAULT_MODULE: &str = "pubber";
pub const DEFAULT_TOPIC: &str = "chatter";
pub const TRANSPORT_SEGMENT: &str = "zenoh";

/// Per-segment override of `<device>/<workspace>/<module>/<transport>/<topic>`.
/// `full = Some("...")` bypasses segment assembly and uses the string verbatim.
#[derive(Debug, Default, Clone)]
pub struct TopicOverrides {
    pub device: Option<String>,
    pub workspace: Option<String>,
    pub module: Option<String>,
    pub topic: Option<String>,
    pub full: Option<String>,
}

impl TopicOverrides {
    /// Render the final Zenoh key expression from this set of overrides.
    /// `full` short-circuits everything else when set.
    pub fn key_expr(&self) -> String {
        if let Some(full) = &self.full {
            return full.clone();
        }
        format!(
            "{}/{}/{}/{}/{}",
            self.device.as_deref().unwrap_or(DEFAULT_DEVICE),
            self.workspace.as_deref().unwrap_or(DEFAULT_WORKSPACE),
            self.module.as_deref().unwrap_or(DEFAULT_MODULE),
            TRANSPORT_SEGMENT,
            self.topic.as_deref().unwrap_or(DEFAULT_TOPIC),
        )
    }
}

pub struct ChatterPublisher<'a> {
    publisher: zenoh::pubsub::Publisher<'a>,
}

impl<'a> ChatterPublisher<'a> {
    /// Declare a publisher with all-default segments. Session must outlive
    /// the publisher (`'a`).
    pub fn open(session: &'a zenoh::Session) -> zenoh::Result<Self> {
        Self::open_with(session, TopicOverrides::default())
    }

    /// Declare a publisher with per-segment overrides.
    pub fn open_with(
        session: &'a zenoh::Session,
        overrides: TopicOverrides,
    ) -> zenoh::Result<Self> {
        let publisher = session
            .declare_publisher(overrides.key_expr())
            .encoding(Encoding::from(WIRE_TAG))
            .wait()?;
        Ok(Self { publisher })
    }

    /// Encode `msg` with prost and publish it. `M` is the prost type your
    /// build generates for `ros2/std/StringStamped`.
    ///
    /// `Vec<u8>`, `String`, and `Bytes` are refused with an error: prost
    /// implements `Message` for them as protobuf wrapper types, so passing
    /// already-serialized bytes here would wrap them a second time. Send
    /// those with [`Self::publish_bytes`].
    pub fn publish<M: prost::Message + 'static>(&self, msg: &M) -> zenoh::Result<()> {
        use std::any::TypeId;
        let id = TypeId::of::<M>();
        if id == TypeId::of::<Vec<u8>>()
            || id == TypeId::of::<String>()
            || id == TypeId::of::<prost::bytes::Bytes>()
        {
            return Err("publish() takes a prost message; send serialized bytes with publish_bytes()".into());
        }
        self.publish_bytes(&msg.encode_to_vec())
    }

    /// Publish bytes you produced yourself. The Zenoh encoding tag
    /// [`WIRE_TAG`] is set by this publisher.
    pub fn publish_bytes(&self, payload: &[u8]) -> zenoh::Result<()> {
        self.publisher.put(payload.to_vec()).wait()?;
        Ok(())
    }
}
